DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 4;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _scope_window_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'D20 scope window: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _scope_window_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'scope_status' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text OR p.new_value IS NULL
                WHEN 'scope_reason' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text OR p.new_value IS NULL
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D20 scope window: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _scope_window_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'scope_status' THEN u.scope_status IS DISTINCT FROM p.old_value::text
                WHEN 'scope_reason' THEN u.scope_reason IS DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D20 scope window: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 4: every planned row writes a value this lane owns (new value)
    SELECT count(*) INTO bad FROM _scope_window_plan p
     WHERE CASE p.column_name
                WHEN 'scope_status' THEN p.new_value NOT IN ('retired', 'in_scope')
                ELSE false END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D20 scope window: % planned row(s) write a value this lane does not own', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _scope_window_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (concat_ws(' | ', u.name, coalesce(u.site_type, 'NULL'), u.lat::text, u.lon::text, coalesce(u.country, 'NULL'), coalesce(u.period_start::text, 'NULL'), coalesce(u.period_end::text, 'NULL'))) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D20 scope window: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _scope_window_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'D20/scope-window', '2026-11-07_mechanical-scope-window', r.change_key, 'authoritative', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'D20 scope window: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _scope_window_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'scope_status' THEN u.scope_status IS DISTINCT FROM p.new_value::text
                WHEN 'scope_reason' THEN u.scope_reason IS DISTINCT FROM p.new_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D20 scope window: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _scope_window_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = '2026-11-07_mechanical-scope-window'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D20 scope window: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-11-07_mechanical-scope-window'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('scope_status', 'scope_reason'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'D20 scope window: this run stamp journalled % row(s) outside unified_sites.(scope_status, scope_reason)', bad;
    END IF;

    -- site invariant: no planned site may be left with this - planned site(s) retired although D50 shows them as disputed, or given a D50 reason
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id FROM _scope_window_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (u.scope_status = 'retired' AND CAST(u.id AS text) IN ('01296632-a2a1-4610-a4a9-d0c3be77b788', '0fd636ac-1a80-4a77-b9d0-a065ae811656', '3c466fde-b751-4065-8de2-bd5c9280afe5', '84b456ff-0b44-4d75-92a4-5cbe22026b95', '8df8659c-49be-4a66-b25a-ecbf96541515', 'c8d2c13e-fd9a-466c-9fdc-fc26ee798ded')) OR u.scope_reason LIKE 'D50 disputed site (owner, 2026-10-19): %';
    IF bad > 0 THEN
        RAISE EXCEPTION 'D20 scope window: % planned site(s) retired although D50 shows them as disputed, or given a D50 reason', bad;
    END IF;

    RAISE NOTICE 'D20 scope window: % of % planned cell(s) changed and journalled over 2 curated site(s)',
        moved, expected;
END $$;

COMMIT;

